"""Structured temporal candidate language with safety gating and bounded hysteresis."""

# EVOLVE-BLOCK-START
MOTION_ACTIONS = ("FORWARD", "VEER_LEFT", "VEER_RIGHT")


def safety_contract(observation, memory):
    """Stop whenever confidence is low or collision-closing risk is high."""
    if (
        float(observation["safety_confidence"]) < 0.60
        or float(observation["closing_risk"]) >= 0.75
    ):
        memory["state"] = "STOPPED"
        memory["commit_action"] = None
        return "STOP", 0.99
    return None


def tracking_contract(observation, memory):
    """Use short confirmation stops and stable alternating scans during target loss."""
    visible = bool(observation["target_visible"])
    reliable = (
        visible
        and float(observation["target_confidence"]) >= 0.55
        and float(observation["target_identity_confidence"]) >= 0.60
    )
    if reliable:
        memory["lost_steps_seen"] = 0
        if int(observation["track_age"]) < 2:
            memory["state"] = "VERIFY"
            return "SLOW_DOWN", 0.80
        return None

    lost_steps = max(0, int(observation["lost_steps"]))
    if memory.get("state") in {"LOCKED", "APPROACH", "REACQUIRE"} and lost_steps <= 1:
        memory["state"] = "REACQUIRE"
        return "STOP", 0.92

    previous_lost = int(memory.get("lost_steps_seen", -1))
    if lost_steps != previous_lost:
        direction = memory.get("scan_direction", "SCAN_LEFT")
        if lost_steps > 1 and lost_steps % 2 == 0:
            direction = "SCAN_RIGHT" if direction == "SCAN_LEFT" else "SCAN_LEFT"
        memory["scan_direction"] = direction
        memory["lost_steps_seen"] = lost_steps
    memory["state"] = "SEARCH"
    return memory.get("scan_direction", "SCAN_LEFT"), 0.75


def propose_moves(observation, memory):
    """Rank center, bearing-correcting, and side-clear movement proposals."""
    bearing = float(observation["target_bearing"])
    candidates = []
    if observation["corridor_center"]:
        candidates.append("FORWARD")
    if bearing < -12.0 and observation["corridor_left"]:
        candidates.append("VEER_LEFT")
    if bearing > 12.0 and observation["corridor_right"]:
        candidates.append("VEER_RIGHT")
    if observation["corridor_left"]:
        candidates.append("VEER_LEFT")
    if observation["corridor_right"]:
        candidates.append("VEER_RIGHT")
    return list(dict.fromkeys(candidates))


def progress_contract(observation, memory, candidates):
    """Apply short action commitment, reversal hysteresis, and stall recovery."""
    if not candidates:
        return None

    previous = memory.get("last_action")
    committed = memory.get("commit_action")
    remaining = int(memory.get("commit_remaining", 0))
    if committed in candidates and remaining > 0:
        memory["commit_remaining"] = remaining - 1
        return committed

    bearing = float(observation["target_bearing"])
    preferred = candidates[0]
    if previous in candidates:
        if previous == "FORWARD" and abs(bearing) <= 24.0:
            preferred = previous
        elif previous in {"VEER_LEFT", "VEER_RIGHT"}:
            opposite = "VEER_RIGHT" if previous == "VEER_LEFT" else "VEER_LEFT"
            if opposite == preferred and abs(bearing) < 20.0:
                preferred = previous

    last_bearing = memory.get("last_bearing")
    if last_bearing is not None and abs(bearing - float(last_bearing)) < 3.0:
        memory["stall_count"] = int(memory.get("stall_count", 0)) + 1
    else:
        memory["stall_count"] = 0

    if int(memory.get("stall_count", 0)) >= 3 and "FORWARD" in candidates:
        preferred = "FORWARD"
        memory["stall_count"] = 0

    memory["last_bearing"] = bearing
    memory["last_action"] = preferred
    memory["commit_action"] = preferred
    memory["commit_remaining"] = 1
    return preferred


def termination_contract(observation, memory):
    """Return a high-confidence stop when no movement proposal is admissible."""
    memory["state"] = "STOPPED"
    memory["commit_action"] = None
    return "STOP", 0.98


def decide(observation, memory):
    """Compose safety, tracking, arrival, progress, and termination contracts."""
    memory = dict(memory or {})

    safety = safety_contract(observation, memory)
    if safety is not None:
        return safety[0], safety[1], memory

    tracking = tracking_contract(observation, memory)
    if tracking is not None:
        return tracking[0], tracking[1], memory

    memory["state"] = "LOCKED"
    if observation["target_distance_class"] == "near":
        if (
            abs(float(observation["heading_error"])) <= 15.0
            and float(observation["target_identity_confidence"]) >= 0.80
        ):
            memory["state"] = "ARRIVED"
            return "ARRIVED", 0.96, memory
        candidates = [
            "VEER_LEFT"
            if float(observation["target_bearing"]) < 0.0
            else "VEER_RIGHT"
        ]
    else:
        candidates = propose_moves(observation, memory)

    action = progress_contract(observation, memory, candidates)
    if action is None:
        fallback = termination_contract(observation, memory)
        return fallback[0], fallback[1], memory

    memory["state"] = "APPROACH"
    return action, 0.90, memory


# EVOLVE-BLOCK-END
